import json,time
from pathlib import Path
import numpy as np
ROOT=Path('/app/output')
def call(cmd):
 response=ROOT/'response.json'; request=ROOT/'request.json'
 if response.exists(): response.unlink()
 request.write_text(json.dumps(cmd))
 while not response.exists():time.sleep(.15)
 d=json.loads(response.read_text())
 if 'error' in d:raise RuntimeError(d)
 return d
Q=[0,1,0,0]
def submit(name, xyz,dt=.05,cameras=None,video='none',fps=5):
 a=np.asarray(xyz)
 if a.shape[1]==3:a=np.column_stack([a,np.tile(Q,(len(a),1))])
 path=str(ROOT/(name+'_actions.npy'));np.save(path,a)
 cmd={'op':'submit','name':name,'path':path,'dt':dt,'video':video,'fps':fps}
 if cameras is not None:cmd['cameras']=cameras
 return call(cmd)
def segment(a,b,speed=.04):
 n=max(1,int(np.ceil(np.linalg.norm(np.array(b)-a)/speed/.05)))
 return np.linspace(a,b,n+1)[1:].tolist()
if __name__=='__main__':
 a=[.0000134,0,.09318]; b=[-.10,-.19,.09]
 p=segment(a,b)+[b]*15
 print(submit('park',p,cameras=['canvas_cam','practice_cam','scene_cam','side_cam']))
 print(call({'op':'obs','name':'park_depth','depth':True}))
